      let html = orig.apply(this, arguments) || '';
      try{
        const t = window.__shareCardTheme || 'cn';
        const swatches =
          '<div class="sc-theme-bar" title="卡片主题">'+
            '<span style="font-size:12px;color:var(--text-hint);">🎨 主题：</span>'+
